21	
22	import java.lang.reflect.InvocationTargetException;
23	import java.util.Collections;
24	import java.util.Dictionary;
25	import java.util.HashMap;
26	import java.util.Hashtable;
27	import java.util.Map;
28	import org.apache.sling.spi.resource.provider.ResourceProvider;
29	import org.osgi.framework.BundleContext;
30	import org.osgi.framework.ServiceRegistration;
31	
32	/**
33	 * Provides an OSGi factory service for a resource provider.  Service
34	 * implementations are usually generated by the AnnotationProcessor so to reduce
35	 * the amount of generated code, as much of the underlying implementation is
36	 * here in default methods.
37	 */
38	@SuppressWarnings("squid:S1214") // There are no constants declared here, not sure why this code smell is being detected
39	public interface DialogResourceProvider {
40	    Class getTargetClass();
41	
42	    default DialogProvider getDialogProvider() {
43	        return (DialogProvider) getTargetClass().getAnnotation(DialogProvider.class);
44	    }
45	
46	    @SuppressWarnings("squid:S2386")
47	    public static Map<Class, ServiceRegistration> registeredProviders = Collections.synchronizedMap(new HashMap<>());
48	
49	    @SuppressWarnings("squid:S1149") // Yes HashTable sucks but it's required here.
50	    default void doActivate(BundleContext bundleContext) throws InstantiationException, IllegalAccessException, IllegalArgumentException, InvocationTargetException, NoSuchMethodException, SecurityException   {
51	        DialogResourceProviderImpl provider = new DialogResourceProviderImpl(getTargetClass(), getDialogProvider());
52	        @SuppressWarnings("UseOfObsoleteCollectionType")
53	        Dictionary<String, Object> props = new Hashtable<>();
54	        props.put(ResourceProvider.PROPERTY_NAME, provider.getRoot());
55	        props.put(ResourceProvider.PROPERTY_ROOT, provider.getRoot());
56	        props.put(ResourceProvider.PROPERTY_USE_RESOURCE_ACCESS_SECURITY, Boolean.FALSE);
57	        ServiceRegistration providerRegistration = bundleContext.registerService(ResourceProvider.class, provider, props);
58	        registeredProviders.put(getTargetClass(), providerRegistration);
59	    }
60	
61	    default void doDeactivate() {
62	        ServiceRegistration providerRegistration = registeredProviders.get(getTargetClass());
63	        if (providerRegistration != null) {
64	            providerRegistration.unregister();
65	        }
66	        registeredProviders.remove(getTargetClass());
67	    }
68	
69	    public static String getServiceClassName(String modelClass) {
70	        String[] parts = modelClass.split("\\.");
71	        String name = "";
72	        String separator = ".";
73	        for (String part : parts) {
74	            char firstChar = part.charAt(0);
75	            String newSeparator = separator;
76	            if (firstChar >= 'A' && firstChar <= 'Z' && separator.equals(".")) {
77	                newSeparator = "$";
78	                name += ".impl";
79	            }
80	            if (name.length() > 0) {
81	                name += separator;
82	            }
83	            name += part;
84	            separator = newSeparator;
85	        }
86	        return name + "_dialogResourceProvider";
87	    }
88	
89	}
